import{_ as i,o as e,c as n,a6 as s}from"./chunks/framework.DycQjAfF.js";const p=JSON.parse('{"title":"Checklist Sebelum Publikasi","description":"Pemeriksaan dan persetujuan yang wajib selesai sebelum handbook dibuka untuk umum.","frontmatter":{"title":"Checklist Sebelum Publikasi","description":"Pemeriksaan dan persetujuan yang wajib selesai sebelum handbook dibuka untuk umum.","status":"ditinjau","dasar":"ketentuan keamanan informasi proyek handbook","diperbarui":"2026-10-20T00:00:00.000Z","kategori":"Tentang Handbook","kata_kunci":["publikasi","deploy","checklist","persetujuan","keamanan informasi","data sensitif","rilis"]},"headers":[],"relativePath":"tentang-handbook/checklist-publikasi.md","filePath":"tentang-handbook/checklist-publikasi.md"}'),t={name:"tentang-handbook/checklist-publikasi.md"};function u(l,a,d,r,o,k){return e(),n("div",null,[...a[0]||(a[0]=[s('<h1 id="checklist-sebelum-publikasi" tabindex="-1">Checklist Sebelum Publikasi <a class="header-anchor" href="#checklist-sebelum-publikasi" aria-label="Permalink to &quot;Checklist Sebelum Publikasi&quot;">​</a></h1><p class="lead">Website ini statis dan hanya memakai <strong>login tampilan</strong> tanpa backend. Login menyembunyikan isi dari pengunjung biasa, tetapi siapa pun yang tahu alamat sebuah file (misalnya gambar) tetap bisa membukanya langsung. Login ini <strong>tidak</strong> membuat website aman untuk data rahasia.</p><h2 id="persetujuan" tabindex="-1">Persetujuan <a class="header-anchor" href="#persetujuan" aria-label="Permalink to &quot;Persetujuan&quot;">​</a></h2><ul class="daftar-periksa"><li>[x] <strong>1. Persetujuan pembimbing atau penanggung jawab.</strong> Ada persetujuan tertulis (email atau pesan) bahwa website boleh dipublikasikan, dan ke mana (publik, intranet, atau terbatas).</li><li><strong>2. Informasi perusahaan diperiksa.</strong> Semua fakta di <a href="/WareHouse/perusahaan/">Profil Perusahaan</a> sesuai dan sumbernya bisa dibuka.</li><li><strong>3. Visi, misi, dan bidang usaha diperiksa.</strong> Isinya sama persis dengan dokumen resmi, atau tidak ditampilkan.</li><li><strong>4. SOP dan prosedur keselamatan diperiksa.</strong> Setiap SOP berstatus <code>disetujui</code>, atau ditandai jelas sebagai draf. Tidak ada ketentuan keselamatan resmi yang dihilangkan.</li><li>[x] <strong>5. Gambar dan dokumen diperiksa.</strong> Setiap foto, screenshot, dan dokumen sudah diizinkan untuk dimuat.</li><li><strong>6. Data sensitif dihapus.</strong> Tidak ada nama dan nomor telepon karyawan, data supplier atau harga, data stok asli, kredensial, maupun denah keamanan.</li><li><strong>7. Logo dan identitas perusahaan disetujui.</strong> Ada izin memakai logo dan warna perusahaan.</li><li><strong>8. Semua URL dan file yang ikut ter-deploy diperiksa.</strong> Jalankan <code>npm run build</code>, lalu <code>npm run cek-publikasi</code>, dan periksa daftar file di folder <code>docs/.vitepress/dist/</code>.</li></ul><h2 id="pemeriksaan-teknis" tabindex="-1">Pemeriksaan teknis <a class="header-anchor" href="#pemeriksaan-teknis" aria-label="Permalink to &quot;Pemeriksaan teknis&quot;">​</a></h2><ul class="daftar-periksa"><li><code>npm run build</code> berhasil tanpa error.</li><li><code>npm run cek-publikasi:ketat</code> lolos. Perintah ini gagal jika masih ada halaman yang belum disetujui atau ada file yang mencurigakan.</li><li>Hapus tag <code>noindex</code> di <code>docs/.vitepress/config.mts</code> hanya jika website memang boleh muncul di mesin pencari.</li><li>Ubah teks status di <code>footer</code> pada <code>config.mts</code> sesuai status publikasi.</li><li>Hapus atau sembunyikan halaman yang belum siap.</li></ul><h2 id="yang-tidak-boleh-dilakukan" tabindex="-1">Yang tidak boleh dilakukan <a class="header-anchor" href="#yang-tidak-boleh-dilakukan" aria-label="Permalink to &quot;Yang tidak boleh dilakukan&quot;">​</a></h2><ul><li>Menaruh file rahasia di <code>docs/public/</code> dengan anggapan &quot;tidak ditautkan, jadi aman&quot;.</li><li>Menaruh kata sandi, token, atau kunci API di file mana pun di proyek ini.</li><li>Mengunggah salinan SOP resmi atau dokumen internal tanpa izin tertulis.</li></ul>',8)])])}const b=i(t,[["render",u]]);export{p as __pageData,b as default};
